// src/routes/select-role.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Building2, Users, Shield, Scale, Briefcase, UserCheck, ChevronRight } from 'lucide-react';
import { Logo } from '../components/logo';
import { Button } from '../components/ui/button'; // ✅ Correctly imported
import api from '../services/api';

const ROLES = [
  { value: 'BUYER', label: 'Property Buyer', icon: Building2, description: 'Looking to purchase properties' },
  { value: 'AGENT', label: 'Real Estate Agent', icon: Users, description: 'Helping clients buy and sell properties' },
  { value: 'LEGAL_REVIEWER', label: 'Legal Reviewer', icon: Scale, description: 'Reviewing legal documents and contracts' },
  { value: 'BANK', label: 'Bank / Lender', icon: Briefcase, description: 'Providing financing for real estate' },
  { value: 'ADMIN', label: 'Admin', icon: Shield, description: 'System administrator' }
];

export default function SelectRole() {
  const navigate = useNavigate();
  const location = useLocation();
  const [selectedRole, setSelectedRole] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [userData, setUserData] = useState({});

  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const token = params.get('token');
    const email = params.get('email');
    const fullName = params.get('fullName');
    const userId = params.get('userId');

    if (!token || !email) {
      navigate('/login');
      return;
    }

    localStorage.setItem('tempToken', token);
    setUserData({ email, fullName, userId });
  }, [location, navigate]);

  const handleSubmit = async () => {
    if (!selectedRole) {
      setError('Please select a role');
      return;
    }

    setLoading(true);
    setError('');

    try {
      const token = localStorage.getItem('tempToken');
      const email = userData.email;
      
      const response = await api.put('/users/role', 
        { role: selectedRole, email: email },
        { headers: { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' } }
      );

      localStorage.setItem('token', token);
      localStorage.removeItem('tempToken');
      
      localStorage.setItem('user', JSON.stringify({
        fullName: userData.fullName || 'User',
        email: userData.email,
        role: selectedRole,
        userId: userData.userId,
        active: true,
        emailVerified: true
      }));

      navigate('/dashboard');
      
    } catch (err) {
      let errorMessage = 'Failed to update role. Please try again.';
      if (err.response?.data?.message) errorMessage = err.response.data.message;
      setError(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  return (
    // ✅ BACKGROUND COLOR FIXED (slate-50 for premium grey look)
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
        className="w-full max-w-3xl bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden"
      >
        <div className="text-center pt-10 pb-6 px-6 border-b border-slate-200">
          <Logo className="justify-center" />
          <h1 className="text-3xl font-bold text-slate-900 mt-6 tracking-tight">Choose Your Role</h1>
          <p className="text-slate-500 mt-2">
            Welcome {userData.fullName || 'User'}! Select how you'll be using Parcel Intelligence
          </p>
        </div>

        {error && (
          <div className="mx-6 mt-4 p-3 rounded-lg bg-red-50 text-red-600 text-sm text-center border border-red-100">
            {error}
          </div>
        )}

        <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-4">
          {ROLES.map((role) => {
            const Icon = role.icon;
            const isSelected = selectedRole === role.value;
            
            return (
              <motion.div
                key={role.value}
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                onClick={() => setSelectedRole(role.value)}
                className={`bg-white cursor-pointer rounded-2xl p-6 transition-all border-2 shadow-sm hover:shadow-md ${
                  isSelected 
                    ? 'border-emerald-500 shadow-lg shadow-emerald-500/20 bg-emerald-50/50' 
                    : 'border-slate-200 hover:border-emerald-300'
                }`}
              >
                <div className="flex items-start gap-4">
                  <div className={`p-3 rounded-xl ${
                    isSelected 
                      ? 'bg-emerald-500/20 text-emerald-600' 
                      : 'bg-slate-100 text-slate-500'
                  }`}>
                    <Icon className="h-6 w-6" />
                  </div>
                  <div className="flex-1">
                    <h3 className={`font-semibold text-base ${
                      isSelected ? 'text-emerald-700' : 'text-slate-900'
                    }`}>
                      {role.label}
                    </h3>
                    <p className="text-sm text-slate-500 mt-1">
                      {role.description}
                    </p>
                  </div>
                  {isSelected && (
                    <div className="text-emerald-500">
                      <UserCheck className="h-5 w-5" />
                    </div>
                  )}
                </div>
              </motion.div>
            );
          })}
        </div>

        <div className="border-t border-slate-200 mt-2 flex flex-col items-center justify-center pt-6 pb-8 px-6 bg-slate-50/30">
          
          {/* ✅ BUTTON NOW VISIBLE AND GREEN */}
          <Button
            onClick={handleSubmit}
            disabled={!selectedRole || loading}
            variant="outline"  // ✅ Green now works because we fixed button.jsx
            className="w-full md:w-64 py-6 text-[16px] font-bold rounded-xl shadow-lg shadow-emerald-500/30 hover:shadow-emerald-500/50 transition-all duration-200 transform hover:scale-[1.02] disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100"
          >
            {loading ? (
              <div className="flex items-center justify-center gap-2">
                <div className="animate-spin rounded-full h-4 w-4 border-2 border-white border-t-transparent"></div>
                Setting up...
              </div>
            ) : (
              <span className="flex items-center justify-center gap-2">
                Continue to Dashboard <ChevronRight className="h-5 w-5" />
              </span>
            )}
          </Button>

          <div className="mt-4 text-center text-xs text-slate-400">
            You can change your role later in settings
          </div>
        </div>
      </motion.div>
    </div>
  );
}