// src/routes/admin.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { PageHeader } from '../components/app-shell';
import { Button } from '../components/ui/button';
import { Badge } from '../components/ui/badge';
import { Input } from '../components/ui/input';
import { 
  Users, Building2, FileText, Shield, AlertTriangle, 
  CheckCircle, UserCheck, UserX, RefreshCw,
  Trash2, Mail, User, Search, Filter, X,
  Home, Briefcase, Scale, Landmark, Crown, BarChart3,
  TrendingUp, TrendingDown, Calendar, MailCheck, MailX,
  AlertCircle, Database
} from 'lucide-react';
import { 
  ResponsiveContainer, PieChart, Pie, Cell, 
  BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid,
  Legend, AreaChart, Area
} from 'recharts';
import { motion } from 'framer-motion';
import api from '../services/api';

export default function AdminPage() {
  const navigate = useNavigate();
  const [users, setUsers] = useState([]);
  const [filteredUsers, setFilteredUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [roleFilter, setRoleFilter] = useState('ALL');
  const [statusFilter, setStatusFilter] = useState('ALL');
  const [verifiedFilter, setVerifiedFilter] = useState('ALL');
  const [stats, setStats] = useState({
    totalUsers: 0,
    activeUsers: 0,
    inactiveUsers: 0,
    verifiedUsers: 0,
    unverifiedUsers: 0,
    roleCounts: {},
    totalProperties: 0,
    availableProperties: 0,
    soldProperties: 0,
    totalReports: 0,
    completedReports: 0,
    totalTransactions: 0,
    completedTransactions: 0,
  });

  const COLORS = ['#10b981', '#3b82f6', '#f59e0b', '#8b5cf6', '#ef4444', '#ec4899'];

  const ROLE_ICONS = {
    'BUYER': Home,
    'AGENT': Briefcase,
    'LEGAL_REVIEWER': Scale,
    'BANK': Landmark,
    'ADMIN': Crown
  };

  const ROLE_COLORS = {
    'BUYER': 'bg-emerald-100 text-emerald-800',
    'AGENT': 'bg-blue-100 text-blue-800',
    'LEGAL_REVIEWER': 'bg-indigo-100 text-indigo-800',
    'BANK': 'bg-amber-100 text-amber-800',
    'ADMIN': 'bg-purple-100 text-purple-800'
  };


  // src/routes/admin.jsx - Add this at the top of the component
useEffect(() => {
  const userData = JSON.parse(localStorage.getItem('user') || '{}');
  console.log('Current user from localStorage:', userData);
  
  if (userData.role !== 'ADMIN') {
    console.log('Not admin, redirecting to dashboard');
    navigate('/dashboard');
    return;
  }
  
  console.log('Admin user confirmed, fetching data...');
  fetchAdminData();
}, []);

  useEffect(() => {
    const userData = JSON.parse(localStorage.getItem('user') || '{}');
    console.log('Current user:', userData);
    
    if (userData.role !== 'ADMIN') {
      console.log('Not admin, redirecting to dashboard');
      navigate('/dashboard');
      return;
    }
    
    fetchAdminData();
  }, []);

  // src/routes/admin.jsx - Update the fetchAdminData function
// src/routes/admin.jsx - Update the fetch call
const fetchAdminData = async () => {
  try {
    setLoading(true);
    setError(null);
    
    console.log('📡 Fetching admin data from API...');
    const token = localStorage.getItem('token');
    
    if (!token) {
      throw new Error('No authentication token found. Please login again.');
    }
    
    // Remove /api from the URL since api.js already adds it
    const response = await api.get('/admin/dashboard', {
      timeout: 10000
    });
    
    console.log('✅ API Response status:', response.status);
    console.log('📊 API Response data:', response.data);
    
    const data = response.data;
    
    if (data.success === false) {
      throw new Error(data.error || data.message || 'Failed to fetch admin data');
    }
    
    const allUsers = data.users || [];
    console.log('👥 Users from API:', allUsers.length);
    
    const roleCounts = {};
    allUsers.forEach(u => {
      const role = u.role || 'UNKNOWN';
      roleCounts[role] = (roleCounts[role] || 0) + 1;
    });
    
    const verifiedUsers = allUsers.filter(u => u.emailVerified).length;
    const unverifiedUsers = allUsers.filter(u => !u.emailVerified).length;
    
    setStats({
      totalUsers: data.totalUsers || allUsers.length,
      activeUsers: data.activeUsers || allUsers.filter(u => u.active).length,
      inactiveUsers: data.inactiveUsers || allUsers.filter(u => !u.active).length,
      verifiedUsers: verifiedUsers,
      unverifiedUsers: unverifiedUsers,
      roleCounts: roleCounts,
      totalProperties: data.totalProperties || 0,
      availableProperties: data.availableProperties || 0,
      soldProperties: data.soldProperties || 0,
      totalReports: data.totalReports || 0,
      completedReports: data.completedReports || 0,
      totalTransactions: data.totalTransactions || 0,
      completedTransactions: data.completedTransactions || 0,
    });
    
    setUsers(allUsers);
    setFilteredUsers(allUsers);
    
  } catch (error) {
    console.error('❌ Error fetching admin data:', error);
    
    let errorMessage = 'Failed to fetch admin data. ';
    
    if (error.code === 'ERR_NETWORK') {
      errorMessage += 'Cannot connect to the backend server. Please make sure the backend is running on port 8080.';
    } else if (error.response?.status === 403) {
      errorMessage += 'You do not have admin permissions.';
    } else if (error.response?.status === 401) {
      errorMessage += 'Your session has expired. Please login again.';
      localStorage.removeItem('token');
      localStorage.removeItem('user');
      setTimeout(() => navigate('/login'), 2000);
    } else {
      errorMessage += error.message || 'Please refresh the page.';
    }
    
    setError(errorMessage);
  } finally {
    setLoading(false);
  }
};

  const deleteUser = async (id) => {
    if (!window.confirm('Are you sure you want to delete this user?')) return;
    try {
      console.log('🗑️ Deleting user:', id);
      await api.delete(`/admin/users/${id}`);
      console.log('✅ User deleted successfully');
      fetchAdminData();
    } catch (error) {
      console.error('❌ Error deleting user:', error);
      alert('Failed to delete user: ' + (error.response?.data?.message || error.message));
    }
  };

  // Filter users
  useEffect(() => {
    let filtered = users;
    
    // Search filter
    if (searchTerm) {
      filtered = filtered.filter(user => 
        user.fullName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        user.email?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }
    
    // Role filter
    if (roleFilter !== 'ALL') {
      filtered = filtered.filter(user => user.role === roleFilter);
    }
    
    // Status filter
    if (statusFilter !== 'ALL') {
      filtered = filtered.filter(user => 
        statusFilter === 'ACTIVE' ? user.active : !user.active
      );
    }
    
    // Email verified filter
    if (verifiedFilter !== 'ALL') {
      filtered = filtered.filter(user => 
        verifiedFilter === 'VERIFIED' ? user.emailVerified : !user.emailVerified
      );
    }
    
    setFilteredUsers(filtered);
  }, [searchTerm, roleFilter, statusFilter, verifiedFilter, users]);

  // Prepare chart data
  const roleChartData = Object.keys(stats.roleCounts || {}).map(role => ({
    name: role,
    value: stats.roleCounts[role]
  }));

  const userActivityData = [
    { name: 'Active', value: stats.activeUsers },
    { name: 'Inactive', value: stats.inactiveUsers },
  ];

  const verificationData = [
    { name: 'Verified', value: stats.verifiedUsers },
    { name: 'Unverified', value: stats.unverifiedUsers },
  ];

  // Clear all filters
  const clearFilters = () => {
    setSearchTerm('');
    setRoleFilter('ALL');
    setStatusFilter('ALL');
    setVerifiedFilter('ALL');
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-96">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-emerald-600"></div>
        <p className="mt-4 text-gray-500">Loading admin data...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-white rounded-2xl p-12 text-center border border-gray-100 shadow-sm max-w-2xl mx-auto">
        <AlertCircle className="h-16 w-16 text-red-500 mx-auto mb-4" />
        <h3 className="text-xl font-semibold text-gray-900 mb-2">Error Loading Data</h3>
        <p className="text-gray-500 mb-6">{error}</p>
        <div className="flex flex-col items-center gap-4">
          <Button onClick={fetchAdminData} className="bg-emerald-600 hover:bg-emerald-700 text-white px-8">
            <RefreshCw className="h-4 w-4 mr-2" />
            Retry
          </Button>
          <p className="text-xs text-gray-400">
            Make sure the backend server is running and you have admin access
          </p>
        </div>
      </div>
    );
  }

  return (
    <>
      <PageHeader 
        title="Admin Dashboard" 
        subtitle={`Manage ${stats.totalUsers} registered users and monitor platform activity`}
        actions={
          <Button 
            onClick={fetchAdminData}
            className="bg-emerald-600 hover:bg-emerald-700 text-white shadow-lg shadow-emerald-500/25"
          >
            <RefreshCw className="h-4 w-4 mr-2" />
            Refresh Data
          </Button>
        }
      />

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white rounded-2xl p-5 border border-gray-100 shadow-sm"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500">Total Registered Users</p>
              <p className="text-2xl font-bold text-gray-900">{stats.totalUsers}</p>
            </div>
            <div className="p-3 rounded-xl bg-emerald-500/10">
              <Users className="h-6 w-6 text-emerald-600" />
            </div>
          </div>
          <div className="mt-2 flex items-center gap-2 text-xs">
            <span className="text-emerald-600 flex items-center">
              <UserCheck className="h-3 w-3 mr-1" /> {stats.activeUsers} Active
            </span>
            <span className="text-gray-300">|</span>
            <span className="text-red-500 flex items-center">
              <UserX className="h-3 w-3 mr-1" /> {stats.inactiveUsers} Inactive
            </span>
          </div>
        </motion.div>

        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="bg-white rounded-2xl p-5 border border-gray-100 shadow-sm"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500">Email Verification</p>
              <p className="text-2xl font-bold text-gray-900">{stats.verifiedUsers}</p>
            </div>
            <div className="p-3 rounded-xl bg-blue-500/10">
              <MailCheck className="h-6 w-6 text-blue-600" />
            </div>
          </div>
          <div className="mt-2 flex items-center gap-2 text-xs">
            <span className="text-emerald-600">{stats.verifiedUsers} Verified</span>
            <span className="text-gray-300">|</span>
            <span className="text-red-500">{stats.unverifiedUsers} Unverified</span>
          </div>
        </motion.div>

        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="bg-white rounded-2xl p-5 border border-gray-100 shadow-sm"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500">Properties</p>
              <p className="text-2xl font-bold text-gray-900">{stats.totalProperties || 0}</p>
            </div>
            <div className="p-3 rounded-xl bg-blue-500/10">
              <Building2 className="h-6 w-6 text-blue-600" />
            </div>
          </div>
          <div className="mt-2 flex items-center gap-2 text-xs">
            <span className="text-emerald-600">{stats.availableProperties || 0} Available</span>
            <span className="text-gray-300">|</span>
            <span className="text-rose-600">{stats.soldProperties || 0} Sold</span>
          </div>
        </motion.div>

        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="bg-white rounded-2xl p-5 border border-gray-100 shadow-sm"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-500">Reports</p>
              <p className="text-2xl font-bold text-gray-900">{stats.totalReports || 0}</p>
            </div>
            <div className="p-3 rounded-xl bg-purple-500/10">
              <FileText className="h-6 w-6 text-purple-600" />
            </div>
          </div>
          <div className="mt-2 text-xs">
            <span className="text-emerald-600">{stats.completedReports || 0} Completed</span>
          </div>
        </motion.div>
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-6">
        {/* Role Distribution Pie Chart */}
        <div className="bg-white rounded-2xl p-6 border border-gray-100 shadow-sm">
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-semibold text-gray-900">Users by Role</h3>
            <Badge className="bg-blue-500">{Object.keys(roleChartData).length} Roles</Badge>
          </div>
          <div className="h-56">
            {roleChartData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={roleChartData}
                    cx="50%"
                    cy="50%"
                    innerRadius={40}
                    outerRadius={70}
                    paddingAngle={5}
                    dataKey="value"
                    label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                  >
                    {roleChartData.map((entry, index) => (
                      <Cell key={index} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            ) : (
              <div className="flex items-center justify-center h-full text-gray-500">
                No users data available
              </div>
            )}
          </div>
        </div>

        {/* User Status Chart */}
        <div className="bg-white rounded-2xl p-6 border border-gray-100 shadow-sm">
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-semibold text-gray-900">User Status</h3>
            <Badge className="bg-emerald-500">Active vs Inactive</Badge>
          </div>
          <div className="h-56">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={userActivityData}
                  cx="50%"
                  cy="50%"
                  innerRadius={40}
                  outerRadius={70}
                  paddingAngle={5}
                  dataKey="value"
                  label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                >
                  <Cell fill="#10b981" />
                  <Cell fill="#ef4444" />
                </Pie>
                <Tooltip />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Email Verification Chart */}
        <div className="bg-white rounded-2xl p-6 border border-gray-100 shadow-sm">
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-semibold text-gray-900">Email Verification</h3>
            <Badge className="bg-blue-500">Verified vs Unverified</Badge>
          </div>
          <div className="h-56">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={verificationData}
                  cx="50%"
                  cy="50%"
                  innerRadius={40}
                  outerRadius={70}
                  paddingAngle={5}
                  dataKey="value"
                  label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                >
                  <Cell fill="#10b981" />
                  <Cell fill="#f59e0b" />
                </Pie>
                <Tooltip />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Users Table with Filters */}
      <div className="bg-white rounded-2xl p-6 border border-gray-100 shadow-sm">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-4">
          <div className="flex items-center gap-2">
            <h3 className="font-semibold text-gray-900">Registered Users</h3>
            <Badge className="bg-emerald-500">{filteredUsers.length} / {stats.totalUsers}</Badge>
          </div>
          
          <div className="flex flex-wrap items-center gap-3">
            {/* Search */}
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
              <Input
                placeholder="Search by name or email..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-9 w-48 md:w-56 h-9 text-sm"
              />
            </div>
            
            {/* Role Filter */}
            <div className="relative">
              <select
                value={roleFilter}
                onChange={(e) => setRoleFilter(e.target.value)}
                className="h-9 px-3 pr-8 border border-gray-300 rounded-lg text-sm bg-white focus:outline-none focus:ring-2 focus:ring-emerald-500"
              >
                <option value="ALL">All Roles</option>
                <option value="BUYER">Buyer</option>
                <option value="AGENT">Agent</option>
                <option value="LEGAL_REVIEWER">Legal Reviewer</option>
                <option value="BANK">Bank</option>
              </select>
            </div>
            
            {/* Status Filter */}
            <div className="relative">
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="h-9 px-3 pr-8 border border-gray-300 rounded-lg text-sm bg-white focus:outline-none focus:ring-2 focus:ring-emerald-500"
              >
                <option value="ALL">All Status</option>
                <option value="ACTIVE">Active</option>
                <option value="INACTIVE">Inactive</option>
              </select>
            </div>
            
            {/* Email Verified Filter */}
            <div className="relative">
              <select
                value={verifiedFilter}
                onChange={(e) => setVerifiedFilter(e.target.value)}
                className="h-9 px-3 pr-8 border border-gray-300 rounded-lg text-sm bg-white focus:outline-none focus:ring-2 focus:ring-emerald-500"
              >
                <option value="ALL">All Verification</option>
                <option value="VERIFIED">Verified</option>
                <option value="UNVERIFIED">Unverified</option>
              </select>
            </div>
            
            {(searchTerm || roleFilter !== 'ALL' || statusFilter !== 'ALL' || verifiedFilter !== 'ALL') && (
              <Button variant="outline" size="sm" onClick={clearFilters} className="h-9">
                <X className="h-4 w-4 mr-1" /> Clear
              </Button>
            )}
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-gray-100">
                <th className="text-left py-3 px-4 text-gray-500 font-medium">ID</th>
                <th className="text-left py-3 px-4 text-gray-500 font-medium">Name</th>
                <th className="text-left py-3 px-4 text-gray-500 font-medium">Email</th>
                <th className="text-left py-3 px-4 text-gray-500 font-medium">Role</th>
                <th className="text-left py-3 px-4 text-gray-500 font-medium">Status</th>
                <th className="text-left py-3 px-4 text-gray-500 font-medium">Email Verified</th>
                <th className="text-left py-3 px-4 text-gray-500 font-medium">Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredUsers.length === 0 ? (
                <tr>
                  <td colSpan="7" className="text-center py-8 text-gray-500">
                    {users.length === 0 ? (
                      <div className="flex flex-col items-center gap-2">
                        <Database className="h-8 w-8 text-gray-300" />
                        <p>No users found in the database</p>
                        <p className="text-xs text-gray-400">Register some users to see them here</p>
                      </div>
                    ) : (
                      'No users match your filters'
                    )}
                  </td>
                </tr>
              ) : (
                filteredUsers.map((user) => {
                  const RoleIcon = ROLE_ICONS[user.role] || User;
                  return (
                    <tr key={user.id} className="border-b border-gray-50 hover:bg-gray-50 transition-colors group">
                      <td className="py-3 px-4 text-gray-500">{user.id}</td>
                      <td className="py-3 px-4 font-medium text-gray-700">{user.fullName}</td>
                      <td className="py-3 px-4 text-gray-600">
                        <div className="flex items-center gap-2">
                          <Mail className="h-3 w-3 text-gray-400" />
                          <span className="truncate max-w-[180px]">{user.email}</span>
                        </div>
                      </td>
                      <td className="py-3 px-4">
                        <Badge className={ROLE_COLORS[user.role] || 'bg-gray-100 text-gray-800'}>
                          <RoleIcon className="h-3 w-3 mr-1" />
                          {user.role || 'BUYER'}
                        </Badge>
                      </td>
                      <td className="py-3 px-4">
                        {user.active ? (
                          <Badge className="bg-emerald-500 text-white hover:bg-emerald-600 transition-colors cursor-pointer">
                            <CheckCircle className="h-3 w-3 mr-1" /> Active
                          </Badge>
                        ) : (
                          <Badge className="bg-red-500 text-white hover:bg-red-600 transition-colors cursor-pointer">
                            <AlertTriangle className="h-3 w-3 mr-1" /> Inactive
                          </Badge>
                        )}
                      </td>
                      <td className="py-3 px-4">
                        {user.emailVerified ? (
                          <Badge className="bg-emerald-100 text-emerald-700 hover:bg-emerald-200 transition-colors">
                            <MailCheck className="h-3 w-3 mr-1" /> Verified
                          </Badge>
                        ) : (
                          <Badge className="bg-amber-100 text-amber-700 hover:bg-amber-200 transition-colors">
                            <MailX className="h-3 w-3 mr-1" /> Unverified
                          </Badge>
                        )}
                      </td>
                      <td className="py-3 px-4">
                        <Button 
                          variant="destructive" 
                          size="sm" 
                          className="h-8 bg-red-500 hover:bg-red-600 text-white"
                          onClick={() => deleteUser(user.id)}
                          disabled={user.role === 'ADMIN'}
                        >
                          <Trash2 className="h-3 w-3" />
                        </Button>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>
    </>
  );
}