// src/routes/profile.jsx
import React, { useState, useEffect } from 'react';
import { PageHeader } from '../components/app-shell';
import { Button } from '../components/ui/button';
import { Input } from '../components/ui/input';
import { Label } from '../components/ui/label';
import { Avatar, AvatarFallback } from '../components/ui/avatar';
import { Badge } from '../components/ui/badge';
import { 
  User, Mail, Building2, Shield, Calendar, Edit2, Save, X, Camera,
  Phone, MapPin, Briefcase, Scale, Landmark, Crown, Lock, Key,
  FileText, TrendingUp, Activity, Users
} from 'lucide-react';
import { motion } from 'framer-motion';
import api from '../services/api';

export default function ProfilePage() {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState(false);
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    role: '',
    phoneNumber: '',
    address: '',
    companyName: '',
    licenseNumber: '',
    barNumber: '',
    bankName: '',
  });
  const [saving, setSaving] = useState(false);
  const [success, setSuccess] = useState('');

  useEffect(() => {
    fetchProfile();
  }, []);

  const fetchProfile = async () => {
    try {
      const response = await api.get('/users/profile');
      setUser(response.data);
      setFormData({
        fullName: response.data.fullName || '',
        email: response.data.email || '',
        role: response.data.role || '',
        phoneNumber: response.data.phoneNumber || '',
        address: response.data.address || '',
        companyName: response.data.companyName || '',
        licenseNumber: response.data.licenseNumber || '',
        barNumber: response.data.barNumber || '',
        bankName: response.data.bankName || '',
      });
    } catch (error) {
      console.error('Error fetching profile:', error);
      const userData = JSON.parse(localStorage.getItem('user') || '{}');
      setUser({
        fullName: userData.fullName || 'User',
        email: userData.email || '',
        role: userData.role || 'BUYER',
        createdAt: new Date().toISOString(),
      });
      setFormData({
        fullName: userData.fullName || 'User',
        email: userData.email || '',
        role: userData.role || 'BUYER',
        phoneNumber: '',
        address: '',
        companyName: '',
        licenseNumber: '',
        barNumber: '',
        bankName: '',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    setSaving(true);
    setSuccess('');
    try {
      await api.put('/users/profile', formData);
      setUser({ ...user, ...formData });
      const userData = JSON.parse(localStorage.getItem('user') || '{}');
      localStorage.setItem('user', JSON.stringify({
        ...userData,
        fullName: formData.fullName,
      }));
      setSuccess('Profile updated successfully!');
      setEditing(false);
      setTimeout(() => setSuccess(''), 3000);
    } catch (error) {
      console.error('Error updating profile:', error);
      alert('Failed to update profile');
    } finally {
      setSaving(false);
    }
  };

  const getInitials = (name) => {
    if (!name) return 'U';
    return name.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2);
  };

  const getRoleIcon = (role) => {
    switch(role?.toUpperCase()) {
      case 'ADMIN': return <Crown className="h-4 w-4" />;
      case 'AGENT': return <Briefcase className="h-4 w-4" />;
      case 'LEGAL_REVIEWER': return <Scale className="h-4 w-4" />;
      case 'BANK': return <Landmark className="h-4 w-4" />;
      default: return <User className="h-4 w-4" />;
    }
  };

  const getRoleColor = (role) => {
    switch(role?.toUpperCase()) {
      case 'ADMIN': return 'bg-purple-100 text-purple-700';
      case 'AGENT': return 'bg-blue-100 text-blue-700';
      case 'LEGAL_REVIEWER': return 'bg-indigo-100 text-indigo-700';
      case 'BANK': return 'bg-amber-100 text-amber-700';
      default: return 'bg-emerald-100 text-emerald-700';
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-96">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-emerald-600"></div>
      </div>
    );
  }

  return (
    <>
      <PageHeader 
        title="My Profile" 
        subtitle="Manage your account settings and preferences"
      />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Profile Card */}
        <div className="lg:col-span-1">
          <div className="bg-white rounded-2xl shadow-lg border border-gray-100 p-6 text-center">
            <div className="relative inline-block">
              <Avatar className="h-24 w-24 mx-auto border-4 border-emerald-100">
                <AvatarFallback className="bg-gradient-to-br from-emerald-500 to-emerald-700 text-white text-2xl font-bold">
                  {getInitials(user?.fullName)}
                </AvatarFallback>
              </Avatar>
              <button className="absolute bottom-0 right-0 p-2 bg-emerald-600 rounded-full text-white hover:bg-emerald-700 transition-colors shadow-lg">
                <Camera className="h-4 w-4" />
              </button>
            </div>
            <h2 className="mt-4 text-xl font-bold text-gray-900">{user?.fullName}</h2>
            <p className="text-sm text-gray-500">{user?.email}</p>
            <Badge className={`mt-3 ${getRoleColor(user?.role)}`}>
              {getRoleIcon(user?.role)}
              <span className="ml-1">{user?.role || 'BUYER'}</span>
            </Badge>
            <div className="mt-4 pt-4 border-t border-gray-100 text-left space-y-2">
              <div className="flex items-center gap-2 text-sm text-gray-600">
                <Calendar className="h-4 w-4 text-gray-400" />
                <span>Member since {new Date(user?.createdAt).toLocaleDateString()}</span>
              </div>
              {user?.phoneNumber && (
                <div className="flex items-center gap-2 text-sm text-gray-600">
                  <Phone className="h-4 w-4 text-gray-400" />
                  <span>{user.phoneNumber}</span>
                </div>
              )}
              {user?.address && (
                <div className="flex items-center gap-2 text-sm text-gray-600">
                  <MapPin className="h-4 w-4 text-gray-400" />
                  <span>{user.address}</span>
                </div>
              )}
            </div>
            <Button 
              onClick={() => setEditing(!editing)}
              className="mt-4 w-full bg-emerald-600 hover:bg-emerald-700 text-white"
            >
              {editing ? <X className="h-4 w-4 mr-2" /> : <Edit2 className="h-4 w-4 mr-2" />}
              {editing ? 'Cancel' : 'Edit Profile'}
            </Button>
          </div>

          {/* Stats */}
          <div className="mt-6 grid grid-cols-2 gap-3">
            <div className="bg-white rounded-xl shadow-lg border border-gray-100 p-4 text-center">
              <FileText className="h-5 w-5 text-emerald-600 mx-auto" />
              <p className="text-xl font-bold text-gray-900 mt-1">12</p>
              <p className="text-xs text-gray-500">Reports</p>
            </div>
            <div className="bg-white rounded-xl shadow-lg border border-gray-100 p-4 text-center">
              <TrendingUp className="h-5 w-5 text-blue-600 mx-auto" />
              <p className="text-xl font-bold text-gray-900 mt-1">8</p>
              <p className="text-xs text-gray-500">Properties</p>
            </div>
          </div>
        </div>

        {/* Profile Form */}
        <div className="lg:col-span-2">
          <div className="bg-white rounded-2xl shadow-lg border border-gray-100 p-6">
            <h3 className="text-lg font-semibold text-gray-900 mb-6">Profile Information</h3>
            
            {success && (
              <div className="mb-4 p-3 rounded-lg bg-emerald-50 text-emerald-700 text-sm border border-emerald-200">
                {success}
              </div>
            )}

            <div className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <Label className="text-sm font-medium text-gray-700">Full Name</Label>
                  <Input
                    value={formData.fullName}
                    onChange={(e) => setFormData({...formData, fullName: e.target.value})}
                    disabled={!editing}
                    className={!editing ? 'bg-gray-50' : ''}
                  />
                </div>
                <div>
                  <Label className="text-sm font-medium text-gray-700">Email Address</Label>
                  <Input
                    value={formData.email}
                    disabled
                    className="bg-gray-50"
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <Label className="text-sm font-medium text-gray-700">Phone Number</Label>
                  <Input
                    value={formData.phoneNumber}
                    onChange={(e) => setFormData({...formData, phoneNumber: e.target.value})}
                    disabled={!editing}
                    className={!editing ? 'bg-gray-50' : ''}
                    placeholder="Enter phone number"
                  />
                </div>
                <div>
                  <Label className="text-sm font-medium text-gray-700">Address</Label>
                  <Input
                    value={formData.address}
                    onChange={(e) => setFormData({...formData, address: e.target.value})}
                    disabled={!editing}
                    className={!editing ? 'bg-gray-50' : ''}
                    placeholder="Enter address"
                  />
                </div>
              </div>

              <div>
                <Label className="text-sm font-medium text-gray-700">Role</Label>
                <Input
                  value={formData.role || 'BUYER'}
                  disabled
                  className="bg-gray-50"
                />
                <p className="text-xs text-gray-400 mt-1">Contact admin to change role</p>
              </div>

              {/* Role-specific fields */}
              {formData.role === 'AGENT' && (
                <div>
                  <Label className="text-sm font-medium text-gray-700">License Number</Label>
                  <Input
                    value={formData.licenseNumber}
                    onChange={(e) => setFormData({...formData, licenseNumber: e.target.value})}
                    disabled={!editing}
                    className={!editing ? 'bg-gray-50' : ''}
                    placeholder="Enter license number"
                  />
                </div>
              )}

              {formData.role === 'LEGAL_REVIEWER' && (
                <div>
                  <Label className="text-sm font-medium text-gray-700">Bar Number</Label>
                  <Input
                    value={formData.barNumber}
                    onChange={(e) => setFormData({...formData, barNumber: e.target.value})}
                    disabled={!editing}
                    className={!editing ? 'bg-gray-50' : ''}
                    placeholder="Enter bar number"
                  />
                </div>
              )}

              {formData.role === 'BANK' && (
                <div>
                  <Label className="text-sm font-medium text-gray-700">Bank Name</Label>
                  <Input
                    value={formData.bankName}
                    onChange={(e) => setFormData({...formData, bankName: e.target.value})}
                    disabled={!editing}
                    className={!editing ? 'bg-gray-50' : ''}
                    placeholder="Enter bank name"
                  />
                </div>
              )}

              {editing && (
                <div className="pt-4 border-t border-gray-100">
                  <Button 
                    onClick={handleSave}
                    disabled={saving}
                    className="w-full bg-emerald-600 hover:bg-emerald-700 text-white"
                  >
                    {saving ? (
                      <>
                        <div className="animate-spin rounded-full h-4 w-4 border-2 border-white border-t-transparent mr-2"></div>
                        Saving...
                      </>
                    ) : (
                      <>
                        <Save className="h-4 w-4 mr-2" />
                        Save Changes
                      </>
                    )}
                  </Button>
                </div>
              )}
            </div>
          </div>

          {/* Security Section */}
          <div className="mt-6 bg-white rounded-2xl shadow-lg border border-gray-100 p-6">
            <h3 className="text-lg font-semibold text-gray-900 mb-4">Security</h3>
            <div className="space-y-3">
              <div className="flex items-center justify-between py-2 border-b border-gray-50">
                <div className="flex items-center gap-3">
                  <Lock className="h-5 w-5 text-gray-400" />
                  <div>
                    <p className="font-medium text-gray-900">Password</p>
                    <p className="text-sm text-gray-500">Last changed 30 days ago</p>
                  </div>
                </div>
                <Button variant="outline" size="sm">
                  <Key className="h-4 w-4 mr-2" />
                  Change Password
                </Button>
              </div>
              <div className="flex items-center justify-between py-2">
                <div className="flex items-center gap-3">
                  <Shield className="h-5 w-5 text-gray-400" />
                  <div>
                    <p className="font-medium text-gray-900">Two-Factor Authentication</p>
                    <p className="text-sm text-gray-500">Add an extra layer of security</p>
                  </div>
                </div>
                <Button variant="outline" size="sm">
                  Enable 2FA
                </Button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}