// src/routes/bank/loans.jsx
import React from 'react';
import { motion } from 'framer-motion';
import { PageHeader } from '../../components/app-shell'; // ✅ Changed to ../../
import { Button } from '../../components/ui/button';       // ✅ Changed to ../../
import { Badge } from '../../components/ui/badge';          // ✅ Changed to ../../
import { FileText, CheckCircle, XCircle, User, Home, DollarSign } from 'lucide-react';

export default function LoanApplications() {
  const mockLoans = [
    { id: 1, property: '123 Main Street, SF', amount: 750000, borrower: 'Swaraj Pakhale', status: 'Pending', date: '2 days ago' },
    { id: 2, property: '456 Oak Ave, LA', amount: 1200000, borrower: 'Archana Pakhale', status: 'Approved', date: '1 week ago' },
  ];

  return (
    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>
      <PageHeader 
        title="Loan Applications" 
        subtitle="Review pending property loans."
        actions={<Button className="bg-emerald-600 text-white"><DollarSign className="mr-2 h-4 w-4" /> New Loan Request</Button>}
      />
      
      <div className="space-y-4">
        {mockLoans.length === 0 ? (
          <div className="p-10 bg-white rounded-2xl border border-slate-100 shadow-sm text-center text-slate-400">
            <FileText className="mx-auto h-12 w-12 text-slate-300 mb-2" />
            <p>No loan applications available for review.</p>
          </div>
        ) : (
          mockLoans.map((loan) => (
            <div key={loan.id} className="bg-white rounded-2xl p-6 border border-slate-100 shadow-sm hover:shadow-md transition-all">
              <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <Home className="h-4 w-4 text-slate-400" />
                    <h3 className="text-lg font-bold text-slate-900">{loan.property}</h3>
                  </div>
                  <div className="flex flex-wrap gap-4 text-sm text-slate-500">
                    <span className="flex items-center gap-1"><User className="h-3 w-3" /> {loan.borrower}</span>
                    <span className="flex items-center gap-1"><FileText className="h-3 w-3" /> {loan.date}</span>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <Badge className={`${loan.status === 'Approved' ? 'bg-emerald-500' : 'bg-amber-500'} text-white`}>
                    {loan.status}
                  </Badge>
                  <Button variant="outline" size="sm" className="text-green-600 border-green-200 hover:bg-green-50"><CheckCircle size={16} className="mr-1"/> Approve</Button>
                  <Button variant="outline" size="sm" className="text-red-600 border-red-200 hover:bg-red-50"><XCircle size={16} className="mr-1"/> Reject</Button>
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </motion.div>
  );
}