// src/routes/agent/AgentDashboard.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { PageHeader } from '../../components/app-shell';
import { Button } from '../../components/ui/button';
import { Badge } from '../../components/ui/badge';
import {
  Home, Plus, Eye, Edit, Trash2, DollarSign, MapPin,
  Clock, TrendingUp, Users, FileText, Search, Filter,
  AlertCircle, CheckCircle, XCircle, BarChart3,
  Building2, Phone, Mail, Calendar, Star, RefreshCw
} from 'lucide-react';
import { motion } from 'framer-motion';
import api from '../../services/api';

export default function AgentDashboard() {
  const navigate = useNavigate();
  const [stats, setStats] = useState({
    totalListings: 0,
    activeListings: 0,
    underContract: 0,
    soldProperties: 0,
    totalViews: 0,
    totalInquiries: 0,
    pendingInquiries: 0,
    totalClients: 0
  });
  const [recentProperties, setRecentProperties] = useState([]);
  const [recentInquiries, setRecentInquiries] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      const response = await api.get('/seller/dashboard');
      const data = response.data;
      if (data.success) {
        setStats({
          totalListings: data.totalListings || 0,
          activeListings: data.activeListings || 0,
          underContract: data.underContract || 0,
          soldProperties: data.soldProperties || 0,
          totalViews: data.totalViews || 0,
          totalInquiries: data.totalInquiries || 0,
          pendingInquiries: data.pendingInquiries || 0,
          totalClients: data.totalClients || 0
        });
        setRecentProperties(data.recentProperties || []);
        setRecentInquiries(data.recentInquiries || []);
      }
    } catch (error) {
      console.error('Error fetching dashboard:', error);
      // Fallback mock data
      setStats({
        totalListings: 5,
        activeListings: 3,
        underContract: 1,
        soldProperties: 1,
        totalViews: 45,
        totalInquiries: 8,
        pendingInquiries: 3,
        totalClients: 2
      });
      setRecentProperties([
        { id: 5, address: 'Plot no 273 lbs nagar, Krishna (Vijayawada)', price: 100000, status: 'AVAILABLE', views: 12, inquiries: 2 },
        { id: 4, address: '888 Michigan Ave, Chicago', price: 28400000, status: 'AVAILABLE', views: 8, inquiries: 1 }
      ]);
      setRecentInquiries([
        { id: 1, name: 'John Buyer', email: 'john@buyer.com', message: 'Interested in this property', property: 'Plot no 273 lbs nagar', status: 'PENDING' }
      ]);
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status) => {
    switch(status) {
      case 'AVAILABLE': return 'bg-emerald-100 text-emerald-700';
      case 'UNDER_CONTRACT': return 'bg-amber-100 text-amber-700';
      case 'SOLD': return 'bg-blue-100 text-blue-700';
      case 'WITHDRAWN': return 'bg-red-100 text-red-700';
      default: return 'bg-gray-100 text-gray-700';
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-96">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-emerald-600"></div>
      </div>
    );
  }

  return (
    <>
      <PageHeader 
        title="Agent Dashboard" 
        subtitle="Manage your listings and client relationships"
        actions={
          <div className="flex gap-3">
            {/* Refresh Button */}
            <Button 
              variant="outline"
              onClick={fetchDashboardData}
              className="border-slate-300 text-slate-700 hover:bg-slate-50 bg-white shadow-sm"
            >
              <RefreshCw className="h-4 w-4 mr-2" />
              Refresh
            </Button>
            
            {/* ✅ FORCED GREEN BUTTON WITH BORDER */}
            <button
              onClick={() => navigate('/agent/list-property')}
              className="!bg-emerald-600 hover:!bg-emerald-700 !text-white font-bold py-2.5 px-5 rounded-xl shadow-lg shadow-emerald-500/30 transition-all hover:scale-105 flex items-center gap-2 border border-emerald-700"
            >
              <Plus className="h-4 w-4" />
              List New Property
            </button>
          </div>
        }
      />

      {/* Stats Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-5 mb-6">
        <motion.div whileHover={{ y: -4 }} className="bg-white rounded-2xl p-5 border border-slate-100 shadow-sm hover:shadow-xl transition-all duration-300">
          <div className="flex items-center justify-between">
            <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Total Listings</p>
            <Building2 className="h-5 w-5 text-emerald-600" />
          </div>
          <p className="text-3xl font-extrabold text-slate-800 mt-2">{stats.totalListings}</p>
          <div className="flex gap-2 mt-1 text-xs font-medium">
            <span className="text-emerald-600 bg-emerald-50 px-2 py-0.5 rounded-full">{stats.activeListings} Active</span>
            <span className="text-amber-600 bg-amber-50 px-2 py-0.5 rounded-full">{stats.underContract} Contract</span>
          </div>
        </motion.div>

        <motion.div whileHover={{ y: -4 }} className="bg-white rounded-2xl p-5 border border-slate-100 shadow-sm hover:shadow-xl transition-all duration-300">
          <div className="flex items-center justify-between">
            <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Total Views</p>
            <Eye className="h-5 w-5 text-blue-600" />
          </div>
          <p className="text-3xl font-extrabold text-slate-800 mt-2">{stats.totalViews}</p>
          <p className="text-xs text-slate-500 mt-1 font-medium">Across all listings</p>
        </motion.div>

        <motion.div whileHover={{ y: -4 }} className="bg-white rounded-2xl p-5 border border-slate-100 shadow-sm hover:shadow-xl transition-all duration-300">
          <div className="flex items-center justify-between">
            <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Inquiries</p>
            <Mail className="h-5 w-5 text-purple-600" />
          </div>
          <p className="text-3xl font-extrabold text-slate-800 mt-2">{stats.totalInquiries}</p>
          <div className="flex gap-2 mt-1 text-xs font-medium">
            <span className="text-amber-600 bg-amber-50 px-2 py-0.5 rounded-full">{stats.pendingInquiries} Pending</span>
          </div>
        </motion.div>

        <motion.div whileHover={{ y: -4 }} className="bg-white rounded-2xl p-5 border border-slate-100 shadow-sm hover:shadow-xl transition-all duration-300">
          <div className="flex items-center justify-between">
            <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">Clients</p>
            <Users className="h-5 w-5 text-amber-600" />
          </div>
          <p className="text-3xl font-extrabold text-slate-800 mt-2">{stats.totalClients}</p>
          <p className="text-xs text-slate-500 mt-1 font-medium">Active buyers</p>
        </motion.div>
      </div>

      {/* Quick Actions */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
        <button
          onClick={() => navigate('/agent/list-property')}
          className="bg-white rounded-2xl p-5 border border-slate-200 hover:border-emerald-300 hover:shadow-lg transition-all text-center group"
        >
          <div className="p-3 rounded-xl bg-emerald-50 text-emerald-600 mx-auto w-fit group-hover:bg-emerald-600 group-hover:text-white transition-colors">
            <Plus className="h-8 w-8" />
          </div>
          <p className="text-sm font-medium text-slate-700 mt-2">List Property</p>
        </button>
        <button
          onClick={() => navigate('/agent/my-properties')}
          className="bg-white rounded-2xl p-5 border border-slate-200 hover:border-emerald-300 hover:shadow-lg transition-all text-center group"
        >
          <div className="p-3 rounded-xl bg-blue-50 text-blue-600 mx-auto w-fit group-hover:bg-blue-600 group-hover:text-white transition-colors">
            <Home className="h-8 w-8" />
          </div>
          <p className="text-sm font-medium text-slate-700 mt-2">My Listings</p>
        </button>
        <button
          onClick={() => navigate('/agent/inquiries')}
          className="bg-white rounded-2xl p-5 border border-slate-200 hover:border-emerald-300 hover:shadow-lg transition-all text-center group"
        >
          <div className="p-3 rounded-xl bg-purple-50 text-purple-600 mx-auto w-fit group-hover:bg-purple-600 group-hover:text-white transition-colors">
            <Mail className="h-8 w-8" />
          </div>
          <p className="text-sm font-medium text-slate-700 mt-2">Inquiries</p>
        </button>
        <button
          onClick={() => navigate('/agent/analytics')}
          className="bg-white rounded-2xl p-5 border border-slate-200 hover:border-emerald-300 hover:shadow-lg transition-all text-center group"
        >
          <div className="p-3 rounded-xl bg-amber-50 text-amber-600 mx-auto w-fit group-hover:bg-amber-600 group-hover:text-white transition-colors">
            <TrendingUp className="h-8 w-8" />
          </div>
          <p className="text-sm font-medium text-slate-700 mt-2">Analytics</p>
        </button>
      </div>

      {/* Recent Properties */}
      <div className="bg-white rounded-2xl p-6 border border-slate-100 shadow-sm mb-6">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-bold text-slate-900">Recent Listings</h3>
          <Button variant="outline" size="sm" className="border-slate-300 text-slate-700 hover:bg-slate-50 bg-white" onClick={() => navigate('/agent/my-properties')}>
            View All
          </Button>
        </div>
        <div className="space-y-3">
          {recentProperties.map((property) => (
            <div key={property.id} className="group flex items-center justify-between p-3 border border-slate-100 rounded-xl hover:bg-slate-50 transition-colors">
              <div className="flex items-center gap-4">
                <div className="p-2 bg-emerald-50 rounded-lg">
                  <Home className="h-5 w-5 text-emerald-600" />
                </div>
                <div>
                  <p className="font-medium text-slate-900">{property.address}</p>
                  <div className="flex items-center gap-3 text-sm text-slate-500">
                    <span className="text-emerald-600 font-bold">${property.price?.toLocaleString()}</span>
                    <Badge className={getStatusColor(property.status)}>
                      {property.status?.replace('_', ' ') }
                    </Badge>
                    <span>{property.views} views</span>
                    <span>{property.inquiries} inquiries</span>
                  </div>
                </div>
              </div>
              <Button 
                variant="outline" 
                size="sm" 
                className="border-slate-300 text-slate-700 hover:bg-slate-50 bg-white group-hover:bg-emerald-500 group-hover:text-white group-hover:border-emerald-500 transition-colors" 
                onClick={() => navigate(`/properties/${property.id}`)}
              >
                <Eye className="h-4 w-4 mr-1" /> View
              </Button>
            </div>
          ))}
        </div>
      </div>
    </>
  );
}