import React, { useState, useEffect } from 'react';
import { PageHeader } from '../components/app-shell';
import { Input } from '../components/ui/input';
import { Button } from '../components/ui/button';
import { Search, Building2 } from 'lucide-react';
import { propertyService } from '../services/api';

export default function PropertiesPage() {
  const [properties, setProperties] = useState([]);
  const [loading, setLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    fetchProperties();
  }, []);

  const fetchProperties = async () => {
    setLoading(true);
    try {
      const response = await propertyService.getAll();
      setProperties(response.data);
    } catch (error) {
      console.error('Error fetching properties:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = async () => {
    if (!searchQuery.trim()) {
      fetchProperties();
      return;
    }
    setLoading(true);
    try {
      const response = await propertyService.search(searchQuery);
      setProperties(response.data);
    } catch (error) {
      console.error('Error searching properties:', error);
    } finally {
      setLoading(false);
    }
  };

  const formatCurrency = (amount) => {
    if (!amount) return '$0';
    return amount >= 1000000 ? `$${(amount / 1000000).toFixed(1)}M` : `$${amount.toLocaleString()}`;
  };

  const getRiskColor = (risk) => {
    if (!risk) return 'text-gray-500 bg-gray-100';
    switch(risk.toLowerCase()) {
      case 'low': return 'text-emerald-600 bg-emerald-500/10';
      case 'medium': return 'text-amber-500 bg-amber-500/10';
      case 'high': return 'text-red-500 bg-red-500/10';
      default: return 'text-gray-500 bg-gray-100';
    }
  };

  return (
    <>
      <PageHeader 
        title="Property Search" 
        subtitle="Find and analyze properties across the US"
        actions={
        // src/routes/properties.jsx - Update search button
<Button 
  onClick={handleSearch} 
  className="bg-emerald-600 hover:bg-emerald-700 text-white shadow-lg shadow-emerald-500/20 hover:shadow-emerald-500/30 transition-all"
>
  <Search className="h-4 w-4 mr-2" />
  Search
</Button>
        }
      />

      <div className="bg-white rounded-2xl shadow-lg border border-gray-100 p-6 mb-6">
        <div className="flex gap-4">
          <Input
            placeholder="Search by address, city, state, or parcel ID..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSearch()}
            className="flex-1"
          />
        </div>
      </div>

      <div className="space-y-4">
        {loading ? (
          <div className="bg-white rounded-2xl shadow-lg border border-gray-100 p-12 text-center">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-emerald-600 mx-auto"></div>
            <p className="mt-4 text-gray-500">Loading properties...</p>
          </div>
        ) : properties.length === 0 ? (
          <div className="glass rounded-2xl p-12 text-center">
            <Building2 className="h-12 w-12 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-medium">No properties found</h3>
            <p className="text-gray-500">Try adjusting your search criteria</p>
          </div>
        ) : (
          properties.map((property) => (
            <div
  key={property.id}
  className="bg-white rounded-2xl shadow-md border border-gray-100 p-6 hover:shadow-xl transition-all duration-300 hover:-translate-y-1"
>
              <div className="flex flex-col md:flex-row md:items-start md:justify-between gap-4">
                <div className="flex-1">
                  <div className="flex items-start justify-between">
                    <div>
                      <h3 className="text-lg font-semibold text-gray-900">
                        {property.address}
                      </h3>
                      <p className="text-gray-600">
                        {property.city}, {property.state} {property.zipCode}
                      </p>
                      <p className="text-xs text-gray-400 mt-1">
                        Parcel ID: {property.parcelId}
                      </p>
                    </div>
                    <span className={`px-3 py-1 rounded-full text-xs font-medium ${getRiskColor(property.risk)}`}>
                      {property.risk || 'Unknown'} Risk
                    </span>
                  </div>
                  
                  <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mt-4">
                    <div>
                      <p className="text-xs text-gray-500">Price</p>
                     <p className="font-semibold text-gray-900">{formatCurrency(property.price)}</p>
                    </div>
                    <div>
                      <p className="text-xs text-gray-500">Size</p>
                     <p className="font-semibold text-gray-900">{property.size || 'N/A'}</p>
                    </div>
                    <div>
                      <p className="text-xs text-gray-500">Type</p>
                      <p className="font-semibold text-gray-900">{property.propertyType || 'N/A'}</p>
                    </div>
                    <div>
                      <p className="text-xs text-gray-500">Cap Rate</p>
                     <p className="font-semibold text-gray-900">{property.capRate || 'N/A'}%</p>
                    </div>
                  </div>
                </div>
                
               <Button
variant="default"
className="shrink-0 bg-emerald-600 hover:bg-emerald-700 text-white"
                  onClick={() => window.location.href = `/properties/${property.id}`}
                >
                  View Details
                </Button>
              </div>
            </div>
          ))
        )}
      </div>
    </>
  );
}