// src/routes/reports.jsx
import React, { useState } from 'react';
import { PageHeader } from '../components/app-shell';
import { Button } from '../components/ui/button';
import { Badge } from '../components/ui/badge';
import { FileText, Download, Eye, Clock, CheckCircle, AlertCircle } from 'lucide-react';
import { motion } from 'framer-motion';

export default function ReportsPage() {
  const [reports] = useState([
    {
      id: 1,
      property: '425 Market Street, SF',
      type: 'Due Diligence Report',
      date: '2024-01-15',
      status: 'Completed',
      riskScore: 18,
    },
    {
      id: 2,
      property: '1200 Brickell Avenue, Miami',
      type: 'Risk Assessment',
      date: '2024-01-12',
      status: 'In Progress',
      riskScore: 42,
    },
    {
      id: 3,
      property: '500 W 33rd Street, NY',
      type: 'Comparables Report',
      date: '2024-01-10',
      status: 'Completed',
      riskScore: 12,
    },
  ]);

  const getStatusBadge = (status) => {
    if (status === 'Completed') {
      return <Badge className="bg-emerald-500"><CheckCircle className="h-3 w-3 mr-1" /> Completed</Badge>;
    } else if (status === 'In Progress') {
      return <Badge className="bg-amber-500"><Clock className="h-3 w-3 mr-1" /> In Progress</Badge>;
    }
    return <Badge variant="outline">{status}</Badge>;
  };

  return (
    <>
      <PageHeader 
        title="Due Diligence Reports" 
        subtitle="View and manage all your property reports"
        actions={
         // src/routes/reports.jsx - Update New Report button
<Button className="bg-emerald-600 hover:bg-emerald-700 text-white shadow-lg shadow-emerald-500/20 hover:shadow-emerald-500/30 transition-all">
  <FileText className="h-4 w-4 mr-2" />
  New Report
</Button>
        }
      />

      <div className="space-y-4">
        {reports.map((report, index) => (
          <motion.div
            key={report.id}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: index * 0.1 }}
            className="glass rounded-2xl p-6 hover:shadow-glow transition-all border border-border"
          >
            <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
              <div className="flex items-start gap-4">
                <div className="p-3 rounded-xl bg-emerald-500/10 text-emerald-600">
                  <FileText className="h-6 w-6" />
                </div>
                <div>
                  <h3 className="font-semibold text-foreground">{report.property}</h3>
                  <p className="text-sm text-muted-foreground">{report.type}</p>
                  <div className="flex flex-wrap items-center gap-3 mt-2">
                    <span className="text-xs text-muted-foreground">{report.date}</span>
                    {getStatusBadge(report.status)}
                    <Badge variant="outline" className="text-xs">
                      Risk Score: {report.riskScore}
                    </Badge>
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <Button variant="outline" size="sm">
                  <Eye className="h-4 w-4 mr-1" /> View
                </Button>
                <Button variant="outline" size="sm">
                  <Download className="h-4 w-4 mr-1" /> PDF
                </Button>
              </div>
            </div>
          </motion.div>
        ))}
      </div>
    </>
  );
}